package main

import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"strconv"
)

// parseAge は文字列を年齢(int)に変換する。
// - 整数として読めなければ errors.New("数値ではありません") を返す(strconv.Atoi のエラーを確かめる)
// - 負の値なら errors.New("負の値です") を返す
// - それ以外は (年齢, nil) を返す
func parseAge(s string) (int, error) {
	age, err := strconv.Atoi(s)
	if err != nil {
		return 0, errors.New("数値ではありません")
	}
	if age < 0 {
		return 0, errors.New("負の値です")
	}
	return age, nil
}

// ---- ここから下は動作確認用(書き換え不要) ----
func main() {
	sc := bufio.NewScanner(os.Stdin)
	for sc.Scan() {
		age, err := parseAge(sc.Text())
		if err != nil {
			fmt.Println("NG:", err)
			continue
		}
		fmt.Println("OK:", age)
	}
}
